import pytest

from inventory.stock import reserve


def test_reserve_reduces_stock() -> None:
    assert reserve(10, 3) == 7


def test_reserve_allows_all_stock() -> None:
    assert reserve(5, 5) == 0


@pytest.mark.parametrize(
    ("available", "requested", "message"),
    [
        (-1, 1, "available stock must not be negative"),
        (5, 0, "requested units must be positive"),
        (5, -2, "requested units must be positive"),
        (5, 6, "requested units exceed available stock"),
    ],
)
def test_reserve_rejects_invalid_requests(
    available: int, requested: int, message: str
) -> None:
    with pytest.raises(ValueError, match=message):
        reserve(available, requested)
